-- ===================================================
-- migration_198: 課長ミッション「インフルエンザ予防接種」
--   ・flu_checkup_examinees : 健診機関の受診者名簿（紙PDFをOCR＋目視確認で取込）。インフルエンザ欄の○＝接種
--       emp_no は社員台帳(employees)との紐付け（生年月日＋カナ氏名で照合。未登録者は NULL）
--   ・flu_manual_vaccinations : 他の病院等で接種した人を画面から「接種済み」にした記録
--   season は年度（'2026' = 令和8年度）。令和8年10月7日〜9日の健診分を初期投入。
-- ===================================================
CREATE TABLE IF NOT EXISTS flu_checkup_examinees (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  season        TEXT NOT NULL,
  checkup_date  TEXT NOT NULL,
  examinee_id   TEXT NOT NULL,
  name_kana     TEXT NOT NULL,
  birth_date    TEXT,
  vaccinated    INTEGER NOT NULL DEFAULT 0,
  emp_no        TEXT,
  note          TEXT,
  source_page   TEXT,
  created_at    TEXT DEFAULT (datetime('now', 'localtime')),
  UNIQUE(season, examinee_id)
);
CREATE INDEX IF NOT EXISTS idx_flu_examinees_emp ON flu_checkup_examinees(season, emp_no);

CREATE TABLE IF NOT EXISTS flu_manual_vaccinations (
  id            INTEGER PRIMARY KEY AUTOINCREMENT,
  season        TEXT NOT NULL,
  emp_no        TEXT NOT NULL,
  vaccinated_at TEXT,
  place         TEXT,
  note          TEXT,
  created_by    INTEGER,
  created_at    TEXT DEFAULT (datetime('now', 'localtime')),
  UNIQUE(season, emp_no)
);

